import { sb } from './config.js';

const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const date=v=>v?new Intl.DateTimeFormat('pt-BR').format(new Date(v+'T12:00:00')):'—';
const dt=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';
const pct=(a,b)=>b?Math.round((a/b)*100):0;
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;
const today=()=>new Date().toISOString().slice(0,10);
const asNum=v=>v===''||v==null?null:Number(v);
const bool=v=>v===true||v==='true'||v==='on';

const state={user:null,me:null,view:'dashboard',activeClientId:localStorage.getItem('wt_aba_active_client')||'',activeSessionId:null,clients:[],professionals:[],assignments:[],supervisionLinks:[],protocols:[],criteria:[],assessments:[],results:[],goals:[],programs:[],targets:[],sessions:[],trials:[],behavior:[],preferences:[],supervisions:[],reports:[],audit:[]};

const titles={dashboard:['Painel clínico','Avaliar → planejar → aplicar → monitorar → reavaliar.'],clients:['Clientes','Prontuário longitudinal e equipe vinculada.'],professionals:['Profissionais','Cadastro, função, supervisão e vínculos clínicos.'],protocols:['Protocolos','Catálogo de avaliações e critérios operacionais.'],assessments:['Avaliações','Aplicação, evidências, escores e reavaliação longitudinal.'],programs:['Programas e metas','Objetivos mensuráveis, programas ABA e alvos.'],sessions:['Aplicador / sessões','Coleta rápida por tentativa, integridade e IOA.'],behavior:['Comportamento e preferência','ABC, mensuração comportamental e avaliação de preferência/reforçadores.'],supervision:['Supervisão','Feedback, integridade, IOA e plano de ação.'],monitor:['Monitoramento','Análise longitudinal e alertas para decisão clínica.'],reports:['Relatórios','Síntese técnica longitudinal e registro de versões.'],audit:['Auditoria','Rastreabilidade das ações do módulo ABA.']};

function flash(message,type='ok'){
  const el=$('#abaFlash');el.textContent=message;el.className=`aba-flash on ${type}`;clearTimeout(flash.t);flash.t=setTimeout(()=>el.className='aba-flash',3200);
}
function client(){return state.clients.find(x=>x.id===state.activeClientId)||null}
function prof(id){return state.professionals.find(x=>x.id===id)||null}
function proto(id){return state.protocols.find(x=>x.id===id)||null}
function statusBadge(s){return `<span class="aba-badge ${esc(s||'')}">${esc(String(s||'—').replaceAll('_',' '))}</span>`}
function requireClient(){if(client())return true;flash('Selecione um cliente para continuar.','bad');return false}
function canAdmin(){return state.me?.role==='admin'}
function canSupervisor(){return ['admin','supervisor'].includes(state.me?.role)}

async function query(table,select='*',configure=null){
  let q=sb.from(table).select(select);if(configure)q=configure(q);const {data,error}=await q;if(error)throw error;return data||[];
}
async function audit(action,entityType,entityId=null,metadata={}){
  try{await sb.from('aba_audit_log').insert({actor_user_id:state.user.id,action,entity_type:entityType,entity_id:entityId,metadata})}catch{}
}

async function authGate(){
  const {data:{session}}=await sb.auth.getSession();
  if(!session){location.replace('/sistema-aba-login.html');return false}
  state.user=session.user;
  const {data,error}=await sb.from('aba_professionals').select('*').eq('user_id',session.user.id).eq('active',true).maybeSingle();
  if(error||!data){await sb.auth.signOut();location.replace('/sistema-aba-login.html?denied=1');return false}
  state.me=data;
  $('#abaUserName').textContent=data.full_name;
  $('#abaUserRole').textContent=`${data.role.toUpperCase()}${data.registration?' · '+data.registration:''}`;
  return true;
}

async function loadAll(){
  const tasks=[
    query('aba_clients','*',q=>q.order('full_name')),
    query('aba_professionals','*',q=>q.order('full_name')),
    query('aba_client_professionals'),
    query('aba_supervision_links'),
    query('aba_protocols','*',q=>q.eq('active',true).order('position')),
    query('aba_protocol_criteria','*',q=>q.eq('active',true).order('position')),
    query('aba_assessments','*',q=>q.order('assessment_date',{ascending:false})),
    query('aba_assessment_results'),
    query('aba_goals','*',q=>q.order('created_at',{ascending:false})),
    query('aba_programs','*',q=>q.order('created_at',{ascending:false})),
    query('aba_targets','*',q=>q.order('position')),
    query('aba_sessions','*',q=>q.order('started_at',{ascending:false})),
    query('aba_trials','*',q=>q.order('attempted_at',{ascending:false})),
    query('aba_behavior_records','*',q=>q.order('occurred_at',{ascending:false})),
    query('aba_preference_assessments','*',q=>q.order('performed_at',{ascending:false})),
    query('aba_supervisions','*',q=>q.order('supervision_date',{ascending:false})),
    query('aba_reports','*',q=>q.order('created_at',{ascending:false})),
    canAdmin()?query('aba_audit_log','*',q=>q.order('created_at',{ascending:false}).limit(300)):Promise.resolve([])
  ];
  const r=await Promise.all(tasks);
  [state.clients,state.professionals,state.assignments,state.supervisionLinks,state.protocols,state.criteria,state.assessments,state.results,state.goals,state.programs,state.targets,state.sessions,state.trials,state.behavior,state.preferences,state.supervisions,state.reports,state.audit]=r;
  if(state.activeClientId&&!state.clients.some(c=>c.id===state.activeClientId))state.activeClientId='';
  renderClientPicker();render();
}

function renderClientPicker(){
  const el=$('#abaActiveClient');
  el.innerHTML='<option value="">Selecionar cliente</option>'+state.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${c.id===state.activeClientId?'selected':''}>${esc(c.preferred_name||c.full_name)}</option>`).join('');
}
function setView(v){state.view=v;$$('.aba-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$$('.aba-view').forEach(x=>x.classList.remove('active'));$(`#abaView-${v}`)?.classList.add('active');const [t,s]=titles[v]||[v,''];$('#abaViewTitle').textContent=t;$('#abaViewSubtitle').textContent=s;render()}
function render(){
  const fn={dashboard:renderDashboard,clients:renderClients,professionals:renderProfessionals,protocols:renderProtocols,assessments:renderAssessments,programs:renderPrograms,sessions:renderSessions,behavior:renderBehavior,supervision:renderSupervision,monitor:renderMonitor,reports:renderReports,audit:renderAudit}[state.view];if(fn)fn();bindViewActions();
}

function renderDashboard(){
  const c=client();const cp=c?state.programs.filter(x=>x.client_id===c.id):[];const cs=c?state.sessions.filter(x=>x.client_id===c.id):[];const ca=c?state.assessments.filter(x=>x.client_id===c.id):[];const due=cp.filter(p=>p.review_date&&p.review_date<=new Date(Date.now()+14*864e5).toISOString().slice(0,10)&&!['closed','paused'].includes(p.status));
  const recent=cs.filter(s=>s.status==='completed').slice(0,6);
  $('#abaView-dashboard').innerHTML=`
  <div class="aba-grid cols-5">
    <div class="aba-card aba-stat"><span>Clientes ativos</span><strong>${state.clients.filter(x=>x.active).length}</strong></div>
    <div class="aba-card aba-stat"><span>Protocolos</span><strong>${state.protocols.length}</strong></div>
    <div class="aba-card aba-stat"><span>Avaliações${c?' do cliente':''}</span><strong>${ca.length}</strong></div>
    <div class="aba-card aba-stat"><span>Programas ativos</span><strong>${cp.filter(x=>!['closed','paused','reserve'].includes(x.status)).length}</strong></div>
    <div class="aba-card aba-stat"><span>Revisões próximas</span><strong>${due.length}</strong></div>
  </div>
  <div class="aba-grid cols-2">
    <div class="aba-card"><div class="aba-section-head"><div><h3>${c?esc(c.preferred_name||c.full_name):'Selecione um cliente'}</h3><p>${c?'Prontuário longitudinal ativo.':'Use o seletor no topo para abrir o prontuário.'}</p></div>${c?'<button class="aba-btn small" data-go="assessments">Nova avaliação</button>':''}</div>${c?dashboardClient(c,ca,cp,cs):'<div class="aba-empty">Nenhum cliente selecionado.</div>'}</div>
    <div class="aba-card"><h3>Alertas clínicos</h3>${c?monitorAlerts(c.id).slice(0,8).map(a=>`<div class="aba-alert ${a.level}">${esc(a.text)}</div>`).join('')||'<div class="aba-alert ok">Nenhum alerta automático com os dados atuais.</div>':'<div class="aba-empty">Selecione um cliente para calcular alertas.</div>'}</div>
  </div>
  <div class="aba-card"><h3>Sessões recentes</h3>${recent.length?`<div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Data</th><th>Profissional</th><th>Status</th><th>Integridade</th><th>IOA</th></tr></thead><tbody>${recent.map(s=>`<tr><td>${dt(s.started_at)}</td><td>${esc(prof(s.professional_id)?.full_name||'—')}</td><td>${statusBadge(s.status)}</td><td>${s.integrity_pct??'—'}%</td><td>${s.ioa_pct??'—'}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="aba-empty">Sem sessões concluídas para o cliente selecionado.</div>'}</div>`;
}
function dashboardClient(c,assess,programs,sessions){
  const team=state.assignments.filter(a=>a.client_id===c.id&&a.active).map(a=>prof(a.professional_id)?.full_name).filter(Boolean);
  const last=assess[0];
  return `<div class="aba-grid cols-2"><div><p><b>Responsável:</b> ${esc(c.guardian_name||'—')}<br><b>Informação clínica:</b> ${esc(c.clinical_info||c.diagnosis||'—')}<br><b>Equipe:</b> ${esc(team.join(', ')||'Sem vínculos')}</p></div><div><p><b>Última avaliação:</b> ${last?`${esc(proto(last.protocol_id)?.name||last.protocol_id)} · ${date(last.assessment_date)}`:'—'}<br><b>Sessões:</b> ${sessions.length}<br><b>Programas:</b> ${programs.length}</p></div></div>`;
}

function renderClients(){
  const rows=state.clients.map(c=>{const team=state.assignments.filter(a=>a.client_id===c.id&&a.active).length;return `<tr><td><b>${esc(c.full_name)}</b>${c.preferred_name?`<br><span class="muted">${esc(c.preferred_name)}</span>`:''}</td><td>${c.birth_date?date(c.birth_date):'—'}</td><td>${esc(c.guardian_name||'—')}</td><td>${team}</td><td>${c.active?statusBadge('active'):statusBadge('closed')}</td><td><button class="aba-btn small secondary" data-client-open="${c.id}">Abrir</button> ${canSupervisor()?`<button class="aba-btn small secondary" data-client-edit="${c.id}">Editar</button> <button class="aba-btn small ghost" data-client-team="${c.id}">Equipe</button>`:''}</td></tr>`}).join('');
  $('#abaView-clients').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>Clientes</h3><p>Cadastro clínico sem exclusão física de histórico.</p></div>${canSupervisor()?'<button class="aba-btn" data-client-new>Novo cliente</button>':''}</div><div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Cliente</th><th>Nascimento</th><th>Responsável</th><th>Equipe</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Nenhum cliente cadastrado.</td></tr>'}</tbody></table></div></div>`;
}

function renderProfessionals(){
  const rows=state.professionals.map(p=>{const sup=state.supervisionLinks.filter(x=>x.supervisee_id===p.id&&x.active).map(x=>prof(x.supervisor_id)?.full_name).filter(Boolean);return `<tr><td><b>${esc(p.full_name)}</b><br><span class="muted">${esc(p.email||'sem e-mail de acesso')}</span></td><td>${esc(p.registration||'—')}</td><td>${esc(p.specialty||'—')}</td><td>${statusBadge(p.role)}</td><td>${esc(sup.join(', ')||'—')}</td><td>${p.active?statusBadge('active'):statusBadge('closed')}</td><td>${canAdmin()?`<button class="aba-btn small secondary" data-prof-edit="${p.id}">Editar</button>`:''}</td></tr>`}).join('');
  $('#abaView-professionals').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>Profissionais e supervisores</h3><p>O cadastro clínico pode existir antes de uma conta de login ser vinculada.</p></div>${canAdmin()?'<div class="aba-top-actions"><button class="aba-btn secondary" data-supervision-link>Novo vínculo de supervisão</button><button class="aba-btn" data-prof-new>Novo profissional</button></div>':''}</div><div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Profissional</th><th>Registro</th><th>Especialidade</th><th>Função</th><th>Supervisor(es)</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows||'<tr><td colspan="7">Nenhum profissional cadastrado.</td></tr>'}</tbody></table></div></div>`;
}

function renderProtocols(){
  const q=$('#abaProtocolSearch')?.value?.toLowerCase()||'';const list=state.protocols.filter(p=>(p.name+' '+p.category+' '+(p.tags||[]).join(' ')).toLowerCase().includes(q));
  $('#abaView-protocols').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>Catálogo de protocolos</h3><p>Instrumentos comerciais são registrados sem reprodução não licenciada de seus itens oficiais.</p></div></div><div class="aba-toolbar"><div class="aba-field"><label>Buscar</label><input id="abaProtocolSearch" placeholder="VB-MAPP, AFLS, preferência, FBA…" value="${esc(q)}"></div></div><div class="aba-protocol-grid">${list.map(p=>{const n=state.criteria.filter(c=>c.protocol_id===p.id).length;return `<article class="aba-protocol"><h4>${esc(p.name)}</h4><p>${esc(p.description||'')}</p><div class="meta">${statusBadge(p.category)}${p.official_license_required?'<span class="aba-badge warn">licença oficial</span>':'<span class="aba-badge ok">operacional</span>'}<span class="aba-badge info">${n} critérios</span></div>${canAdmin()?`<div style="margin-top:9px"><button class="aba-btn small secondary" data-criterion-new="${p.id}">Adicionar critério</button></div>`:''}</article>`}).join('')||'<div class="aba-empty">Nenhum protocolo encontrado.</div>'}</div></div>`;
}

function renderAssessments(){
  const c=client();if(!c){$('#abaView-assessments').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente para abrir avaliações.</div></div>';return}
  const list=state.assessments.filter(a=>a.client_id===c.id);const rows=list.map(a=>{const rs=state.results.filter(r=>r.assessment_id===a.id);const tested=rs.filter(r=>r.result_state==='tested');const score=tested.reduce((s,r)=>s+(Number(r.score)||0),0);return `<tr><td>${date(a.assessment_date)}</td><td><b>${esc(proto(a.protocol_id)?.name||a.protocol_id)}</b></td><td>${esc(prof(a.evaluator_id)?.full_name||'—')}</td><td>${statusBadge(a.status)}</td><td>${tested.length}</td><td>${score.toFixed(1)}</td><td>${a.reeval_due?date(a.reeval_due):'—'}</td><td><button class="aba-btn small secondary" data-assessment-open="${a.id}">Abrir</button></td></tr>`}).join('');
  $('#abaView-assessments').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>Avaliações · ${esc(c.preferred_name||c.full_name)}</h3><p>Escores, evidências, contexto, independência, generalização e manutenção.</p></div><button class="aba-btn" data-assessment-new>Nova avaliação</button></div><div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Data</th><th>Protocolo</th><th>Avaliador</th><th>Status</th><th>Itens</th><th>Soma</th><th>Reavaliar</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="8">Nenhuma avaliação registrada.</td></tr>'}</tbody></table></div></div><div id="abaAssessmentDetail"></div>`;
}
function assessmentDetail(id){
  const a=state.assessments.find(x=>x.id===id);if(!a)return;const rs=state.results.filter(r=>r.assessment_id===id);const p=proto(a.protocol_id);const prior=state.assessments.filter(x=>x.client_id===a.client_id&&x.protocol_id===a.protocol_id&&x.id!==a.id&&x.assessment_date<a.assessment_date)[0];const priorRs=prior?state.results.filter(r=>r.assessment_id===prior.id):[];
  $('#abaAssessmentDetail').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>${esc(p?.name||a.protocol_id)}</h3><p>${date(a.assessment_date)} · ${esc(a.notes||'Sem observação geral.')}</p></div><div class="aba-top-actions"><button class="aba-btn secondary" data-result-new="${a.id}">Registrar item</button><button class="aba-btn ghost" data-assessment-edit="${a.id}">Editar avaliação</button></div></div>${prior?`<div class="aba-alert ok">Comparação disponível com ${date(prior.assessment_date)}: aplicação anterior contém ${priorRs.filter(x=>x.result_state==='tested').length} itens testados.</div>`:''}<div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Código/domínio</th><th>Critério</th><th>Estado</th><th>Escore</th><th>Independência</th><th>Generalização</th><th>Evidência</th></tr></thead><tbody>${rs.map(r=>{const cr=state.criteria.find(x=>x.id===r.criterion_id);return `<tr><td>${esc(r.custom_code||cr?.criterion_code||'—')}<br><span class="muted">${esc(r.domain||cr?.domain||'—')}</span></td><td>${esc(cr?.title||'Registro inserido pelo avaliador')}</td><td>${statusBadge(r.result_state)}</td><td>${r.score??'—'}</td><td>${r.opportunities?pct(r.independent_responses||0,r.opportunities)+'%':'—'}</td><td>${r.generalized?'Sim':'—'} / ${r.maintained?'Mantém':'—'}</td><td>${esc(r.evidence||r.notes||'—')}</td></tr>`}).join('')||'<tr><td colspan="7">Nenhum item registrado.</td></tr>'}</tbody></table></div></div>`;
  bindViewActions();
}

function renderPrograms(){
  const c=client();if(!c){$('#abaView-programs').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}
  const goals=state.goals.filter(g=>g.client_id===c.id);const programs=state.programs.filter(p=>p.client_id===c.id);
  $('#abaView-programs').innerHTML=`<div class="aba-grid cols-2"><div class="aba-card"><div class="aba-section-head"><div><h3>Metas clínicas</h3><p>Mensuráveis, priorizadas e com data de revisão.</p></div><button class="aba-btn small" data-goal-new>Nova meta</button></div><div class="aba-list">${goals.map(g=>`<div class="aba-list-item"><header><strong>${esc(g.title)}</strong>${statusBadge(g.status)}</header><p>${esc(g.description||g.target||'—')}</p><small>${esc(g.domain||'Sem domínio')} · prioridade ${esc(g.priority)} · revisão ${g.review_date?date(g.review_date):'—'}</small></div>`).join('')||'<div class="aba-empty">Nenhuma meta criada.</div>'}</div></div><div class="aba-card"><div class="aba-section-head"><div><h3>Programas ABA</h3><p>Objetivo, definição operacional, SD, ensino, prompts e critérios.</p></div><button class="aba-btn small" data-program-new>Novo programa</button></div><div>${programs.map(programCard).join('')||'<div class="aba-empty">Nenhum programa criado.</div>'}</div></div></div>`;
}
function programCard(p){const tg=state.targets.filter(t=>t.program_id===p.id);return `<article class="aba-program"><div class="aba-program-head"><div><h4>${esc(p.name)}</h4><div>${statusBadge(p.status)} ${statusBadge(p.measure)}</div></div><button class="aba-btn small secondary" data-program-edit="${p.id}">Editar</button></div><div class="facts"><div class="aba-fact"><b>Objetivo</b><span>${esc(p.objective||'—')}</span></div><div class="aba-fact"><b>Definição operacional</b><span>${esc(p.operational_definition||'—')}</span></div><div class="aba-fact"><b>Critério de aquisição</b><span>${esc(p.acquisition_criterion||'—')}</span></div></div><div style="margin-top:9px"><b style="font-size:10px">Alvos (${tg.length})</b><div class="aba-list" style="margin-top:6px">${tg.map(t=>`<div class="aba-list-item"><header><strong>${esc(t.name)}</strong>${statusBadge(t.status)}</header><p>${esc(t.mastery_criterion||t.expected_response||'—')}</p></div>`).join('')||'<div class="aba-empty">Sem alvos.</div>'}</div><button class="aba-btn small ghost" style="margin-top:7px" data-target-new="${p.id}">Adicionar alvo</button></div></article>`}

function renderSessions(){
  const c=client();if(!c){$('#abaView-sessions').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}
  const sessions=state.sessions.filter(s=>s.client_id===c.id);const active=state.activeSessionId?state.sessions.find(s=>s.id===state.activeSessionId):sessions.find(s=>s.status==='open');if(active)state.activeSessionId=active.id;
  $('#abaView-sessions').innerHTML=`<div class="aba-grid cols-2"><div class="aba-card"><div class="aba-section-head"><div><h3>Sessões</h3><p>Registro longitudinal por profissional e contexto.</p></div><button class="aba-btn" data-session-new>Iniciar sessão</button></div><div class="aba-list">${sessions.slice(0,20).map(s=>`<div class="aba-list-item"><header><strong>${dt(s.started_at)} · ${esc(prof(s.professional_id)?.full_name||'—')}</strong>${statusBadge(s.status)}</header><p>${esc(s.context||s.modality||'—')}</p><div style="margin-top:7px"><button class="aba-btn small secondary" data-session-open="${s.id}">Abrir</button> ${s.status==='open'?`<button class="aba-btn small success" data-session-close="${s.id}">Finalizar</button>`:''}</div></div>`).join('')||'<div class="aba-empty">Nenhuma sessão.</div>'}</div></div><div class="aba-card"><h3>Aplicador rápido</h3>${active?renderApplicator(active):'<div class="aba-empty">Inicie ou abra uma sessão para registrar tentativas.</div>'}</div></div>`;
}
function renderApplicator(s){const programs=state.programs.filter(p=>p.client_id===s.client_id&&!['closed','paused','reserve'].includes(p.status));const tr=state.trials.filter(t=>t.session_id===s.id);return `<div class="aba-alert ok">Sessão aberta em ${dt(s.started_at)} · ${esc(s.context||s.modality||'contexto não informado')} · ${tr.length} registros.</div>${programs.map(p=>{const pTr=tr.filter(t=>t.program_id===p.id);return `<div class="aba-session-program"><b>${esc(p.name)}</b><p style="font-size:11px;color:#647984">${esc(p.sd_instruction||p.objective||'Sem SD cadastrada')}</p><div class="aba-trial-buttons"><button class="ind" data-trial="independent_correct" data-program="${p.id}" data-session="${s.id}">Correta independente</button><button class="prompt" data-trial="prompted_correct" data-program="${p.id}" data-session="${s.id}">Correta com ajuda</button><button class="error" data-trial="incorrect" data-program="${p.id}" data-session="${s.id}">Incorreta</button><button class="error" data-trial="no_response" data-program="${p.id}" data-session="${s.id}">Sem resposta</button><button data-trial="alternative_response" data-program="${p.id}" data-session="${s.id}">Resposta alternativa</button><button class="warn" data-trial="interfering_behavior" data-program="${p.id}" data-session="${s.id}">Interferente</button></div><p style="margin:7px 0 0;font-size:10px">Tentativas: ${pTr.length} · independência ${pct(pTr.filter(x=>x.result==='independent_correct').length,pTr.length)}%</p></div>`}).join('')||'<div class="aba-empty">Não há programas ativos para aplicação.</div>'}`}

function renderBehavior(){
  const c=client();if(!c){$('#abaView-behavior').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}
  const br=state.behavior.filter(x=>x.client_id===c.id);const pr=state.preferences.filter(x=>x.client_id===c.id);
  $('#abaView-behavior').innerHTML=`<div class="aba-grid cols-2"><div class="aba-card"><div class="aba-section-head"><div><h3>Registro ABC e mensuração</h3><p>Antecedente, resposta, consequência, função hipotetizada e medida.</p></div><button class="aba-btn small" data-behavior-new>Novo registro</button></div><div class="aba-list">${br.slice(0,30).map(r=>`<div class="aba-list-item"><header><strong>${dt(r.occurred_at)} · ${esc(r.topography)}</strong><span class="aba-badge warn">${esc(r.hypothesized_function||'função indefinida')}</span></header><p><b>A:</b> ${esc(r.antecedent||'—')}<br><b>C:</b> ${esc(r.consequence||'—')}<br><b>Medida:</b> freq ${r.frequency??'—'} · duração ${r.duration_seconds??'—'}s · latência ${r.latency_seconds??'—'}s</p></div>`).join('')||'<div class="aba-empty">Sem registros ABC.</div>'}</div></div><div class="aba-card"><div class="aba-section-head"><div><h3>Preferência e reforçadores</h3><p>MSWO, pareada, operante livre e validação breve.</p></div><button class="aba-btn small" data-preference-new>Nova avaliação</button></div><div class="aba-list">${pr.slice(0,20).map(r=>`<div class="aba-list-item"><header><strong>${dt(r.performed_at)} · ${esc(r.assessment_type)}</strong></header><p><b>Itens:</b> ${esc((r.items||[]).map(x=>typeof x==='string'?x:x.name||x.item).filter(Boolean).join(', ')||'—')}<br><b>Ranking:</b> ${esc((r.ranking||[]).map(x=>typeof x==='string'?x:x.name||x.item).filter(Boolean).join(' > ')||'—')}</p></div>`).join('')||'<div class="aba-empty">Sem avaliação de preferência.</div>'}</div></div></div>`;
}

function renderSupervision(){
  const c=client();if(!c){$('#abaView-supervision').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}
  const list=state.supervisions.filter(x=>x.client_id===c.id);$('#abaView-supervision').innerHTML=`<div class="aba-card"><div class="aba-section-head"><div><h3>Supervisões</h3><p>Integridade, IOA, feedback e plano de ação preservados no histórico.</p></div>${canSupervisor()?'<button class="aba-btn" data-supervision-new>Registrar supervisão</button>':''}</div><div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Data</th><th>Supervisor</th><th>Supervisionado</th><th>Integridade</th><th>IOA</th><th>Feedback</th><th>Plano</th></tr></thead><tbody>${list.map(s=>`<tr><td>${dt(s.supervision_date)}</td><td>${esc(prof(s.supervisor_id)?.full_name||'—')}</td><td>${esc(prof(s.supervisee_id)?.full_name||'—')}</td><td>${s.integrity_pct??'—'}%</td><td>${s.ioa_pct??'—'}%</td><td>${esc(s.feedback||'—')}</td><td>${esc(s.action_plan||'—')}</td></tr>`).join('')||'<tr><td colspan="7">Nenhuma supervisão registrada.</td></tr>'}</tbody></table></div></div>`;
}

function monitorProgram(p,cid){
  const sessionIds=new Set(state.sessions.filter(s=>s.client_id===cid).map(s=>s.id));const tr=state.trials.filter(t=>sessionIds.has(t.session_id)&&t.program_id===p.id);const correct=tr.filter(t=>['independent_correct','prompted_correct'].includes(t.result)).length;const ind=tr.filter(t=>t.result==='independent_correct').length;const prompted=tr.filter(t=>t.result==='prompted_correct').length;const inter=tr.filter(t=>t.result==='interfering_behavior').length;return {n:tr.length,accuracy:pct(correct,tr.length),independence:pct(ind,tr.length),prompt:pct(prompted,tr.length),interfering:pct(inter,tr.length)};
}
function monitorAlerts(cid){
  const out=[];const ps=state.programs.filter(p=>p.client_id===cid&&!['closed','reserve'].includes(p.status));ps.forEach(p=>{const m=monitorProgram(p,cid);if(m.n>=5&&m.prompt>=50)out.push({level:'',text:`${p.name}: ${m.prompt}% das tentativas corretas ocorreram com ajuda; revisar fading e controle de estímulos.`});if(m.n>=5&&m.accuracy<50)out.push({level:'danger',text:`${p.name}: acurácia ${m.accuracy}% em ${m.n} tentativas; revisar dificuldade, procedimento e reforçamento.`});if(m.n>=5&&m.interfering>=30)out.push({level:'danger',text:`${p.name}: comportamento interferente em ${m.interfering}% dos registros; revisar variáveis antecedentes e hipótese funcional.`});if(p.review_date&&p.review_date<=today())out.push({level:'',text:`${p.name}: data de revisão ${date(p.review_date)} atingida.`});});state.sessions.filter(s=>s.client_id===cid&&s.status==='completed').slice(0,10).forEach(s=>{if(s.integrity_pct!=null&&Number(s.integrity_pct)<80)out.push({level:'danger',text:`Sessão de ${dt(s.started_at)}: integridade ${s.integrity_pct}% (<80%). Interpretar desempenho com cautela.`});if(s.ioa_pct!=null&&Number(s.ioa_pct)<80)out.push({level:'danger',text:`Sessão de ${dt(s.started_at)}: IOA ${s.ioa_pct}% (<80%). Revisar definição operacional e concordância.`})});return out;
}
function renderMonitor(){
  const c=client();if(!c){$('#abaView-monitor').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}
  const ps=state.programs.filter(p=>p.client_id===c.id&&!['closed','reserve'].includes(p.status));const alerts=monitorAlerts(c.id);$('#abaView-monitor').innerHTML=`<div class="aba-grid cols-2"><div class="aba-card"><h3>Evolução por programa</h3>${ps.map(p=>{const m=monitorProgram(p,c.id);return `<div class="aba-monitor-row"><div><b>${esc(p.name)}</b><br><small>${m.n} tentativas · ${esc(p.status)}</small></div><div><small>Independência ${m.independence}%</small><div class="aba-progress"><span style="width:${m.independence}%"></span></div><small>Acurácia ${m.accuracy}% · ajuda ${m.prompt}% · interferente ${m.interfering}%</small></div><strong>${m.independence}%</strong></div>`}).join('')||'<div class="aba-empty">Sem programas ativos.</div>'}</div><div class="aba-card"><h3>Alertas de decisão</h3>${alerts.map(a=>`<div class="aba-alert ${a.level}">${esc(a.text)}</div>`).join('')||'<div class="aba-alert ok">Nenhum alerta automático com os dados atuais.</div>'}</div></div>`;
}

function buildReportData(c){
  const assessments=state.assessments.filter(a=>a.client_id===c.id);const programs=state.programs.filter(p=>p.client_id===c.id);const sessions=state.sessions.filter(s=>s.client_id===c.id);const team=state.assignments.filter(a=>a.client_id===c.id&&a.active).map(a=>({role:a.assignment_role,name:prof(a.professional_id)?.full_name}));return {generated_at:new Date().toISOString(),client:{id:c.id,name:c.full_name,preferred_name:c.preferred_name,birth_date:c.birth_date,guardian:c.guardian_name,clinical_info:c.clinical_info,diagnosis:c.diagnosis},team,assessments:assessments.map(a=>({date:a.assessment_date,protocol:proto(a.protocol_id)?.name||a.protocol_id,status:a.status,reeval_due:a.reeval_due,items:state.results.filter(r=>r.assessment_id===a.id).length})),programs:programs.map(p=>({...p,metrics:monitorProgram(p,c.id)})),sessions:sessions.map(s=>({started_at:s.started_at,ended_at:s.ended_at,professional:prof(s.professional_id)?.full_name,status:s.status,integrity_pct:s.integrity_pct,ioa_pct:s.ioa_pct})),alerts:monitorAlerts(c.id).map(x=>x.text)}
}
function reportHTML(data){return `<div class="aba-report"><h1>RELATÓRIO DE ACOMPANHAMENTO ABA</h1><p style="text-align:center">Walef Teixeira · Sistema ABA · documento gerado em ${dt(data.generated_at)}</p><h2>1. Identificação</h2><p><b>Cliente:</b> ${esc(data.client.name)}<br><b>Data de nascimento:</b> ${data.client.birth_date?date(data.client.birth_date):'—'}<br><b>Responsável:</b> ${esc(data.client.guardian||'—')}<br><b>Informação clínica:</b> ${esc(data.client.clinical_info||data.client.diagnosis||'—')}</p><h2>2. Equipe</h2><p>${esc(data.team.map(x=>`${x.name||'—'} (${x.role})`).join('; ')||'Sem equipe vinculada.')}</p><h2>3. Avaliações</h2>${data.assessments.length?`<table><thead><tr><th>Data</th><th>Protocolo</th><th>Status</th><th>Itens</th><th>Reavaliação</th></tr></thead><tbody>${data.assessments.map(a=>`<tr><td>${date(a.date)}</td><td>${esc(a.protocol)}</td><td>${esc(a.status)}</td><td>${a.items}</td><td>${a.reeval_due?date(a.reeval_due):'—'}</td></tr>`).join('')}</tbody></table>`:'<p>Sem avaliações registradas.</p>'}<h2>4. Programas e evolução</h2>${data.programs.map(p=>`<h3>${esc(p.name)}</h3><p><b>Status:</b> ${esc(p.status)} · <b>Medida:</b> ${esc(p.measure)}<br><b>Objetivo:</b> ${esc(p.objective||'—')}<br><b>Definição operacional:</b> ${esc(p.operational_definition||'—')}<br><b>Critério:</b> ${esc(p.acquisition_criterion||'—')}<br><b>Dados:</b> ${p.metrics.n} tentativas; independência ${p.metrics.independence}%; acurácia ${p.metrics.accuracy}%.</p>`).join('')||'<p>Sem programas.</p>'}<h2>5. Sessões</h2><p>Total registrado: ${data.sessions.length}. Sessões concluídas: ${data.sessions.filter(s=>s.status==='completed').length}.</p><h2>6. Alertas e revisão</h2>${data.alerts.length?`<ul>${data.alerts.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:'<p>Sem alertas automáticos.</p>'}<h2>7. Observação técnica</h2><p>A interpretação deve considerar qualidade da mensuração, integridade de aplicação, concordância entre observadores quando pertinente, contexto e validade social. Alterações no plano devem ser justificadas pelos dados e pela análise clínica.</p><p><b>Responsável técnico do sistema:</b> Walef Lincoln de Souza Teixeira — Psicólogo · CRP 05/85580.</p></div>`}
function renderReports(){
  const c=client();if(!c){$('#abaView-reports').innerHTML='<div class="aba-card"><div class="aba-empty">Selecione um cliente.</div></div>';return}const data=buildReportData(c);const saved=state.reports.filter(r=>r.client_id===c.id);$('#abaView-reports').innerHTML=`<div class="aba-card aba-no-print"><div class="aba-section-head"><div><h3>Relatório longitudinal</h3><p>Prévia gerada apenas a partir dos dados efetivamente registrados.</p></div><div class="aba-top-actions"><button class="aba-btn secondary" data-report-save>Salvar versão</button><button class="aba-btn" data-report-print>Imprimir / PDF</button></div></div><p>Versões salvas: ${saved.length}.</p></div><div class="aba-card" id="abaPrintableReport">${reportHTML(data)}</div>`;
}
function renderAudit(){
  if(!canAdmin()){$('#abaView-audit').innerHTML='<div class="aba-card"><div class="aba-empty">Auditoria completa disponível apenas para administrador ABA.</div></div>';return}$('#abaView-audit').innerHTML=`<div class="aba-card"><h3>Trilha de auditoria</h3><div class="aba-table-wrap"><table class="aba-table"><thead><tr><th>Data</th><th>Ação</th><th>Entidade</th><th>ID</th><th>Metadados</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type)}</td><td>${esc(a.entity_id||'—')}</td><td>${esc(JSON.stringify(a.metadata||{}))}</td></tr>`).join('')||'<tr><td colspan="5">Sem eventos registrados.</td></tr>'}</tbody></table></div></div>`;
}

function openModal(title,body,onSave,saveLabel='Salvar'){
  $('#abaModalTitle').textContent=title;$('#abaModalBody').innerHTML=body;$('#abaModalSave').textContent=saveLabel;$('#abaModal').classList.add('on');$('#abaModalSave').onclick=async()=>{try{$('#abaModalSave').disabled=true;await onSave($('#abaModalBody'));closeModal();await loadAll();flash('Registro salvo.')}catch(err){console.error(err);flash(err?.message||String(err),'bad')}finally{$('#abaModalSave').disabled=false}};
}
function closeModal(){$('#abaModal').classList.remove('on');$('#abaModalBody').innerHTML=''}
function formData(root){const out={};root.querySelectorAll('[name]').forEach(el=>{out[el.name]=el.type==='checkbox'?el.checked:el.value});return out}
function optionProfessionals(selected=''){return state.professionals.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.full_name)} · ${esc(p.role)}</option>`).join('')}
function optionProtocols(selected=''){return state.protocols.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}
function optionGoals(selected=''){return state.goals.filter(g=>g.client_id===state.activeClientId).map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>${esc(g.title)}</option>`).join('')}

function clientModal(existing=null){const c=existing||{};openModal(existing?'Editar cliente':'Novo cliente',`<div class="aba-form-grid"><div class="aba-field wide"><label>Nome completo *</label><input name="full_name" required value="${esc(c.full_name||'')}"></div><div class="aba-field"><label>Nome preferido</label><input name="preferred_name" value="${esc(c.preferred_name||'')}"></div><div class="aba-field"><label>Nascimento</label><input name="birth_date" type="date" value="${esc(c.birth_date||'')}"></div><div class="aba-field"><label>Responsável</label><input name="guardian_name" value="${esc(c.guardian_name||'')}"></div><div class="aba-field"><label>Telefone</label><input name="guardian_phone" value="${esc(c.guardian_phone||'')}"></div><div class="aba-field"><label>E-mail responsável</label><input name="guardian_email" type="email" value="${esc(c.guardian_email||'')}"></div><div class="aba-field"><label>Escola</label><input name="school" value="${esc(c.school||'')}"></div><div class="aba-field"><label>Diagnóstico informado</label><input name="diagnosis" value="${esc(c.diagnosis||'')}"></div><div class="aba-field wide"><label>Informação clínica</label><textarea name="clinical_info">${esc(c.clinical_info||'')}</textarea></div><div class="aba-field wide"><label>Observações</label><textarea name="notes">${esc(c.notes||'')}</textarea></div><div class="aba-field"><label>Status</label><select name="active"><option value="true" ${c.active!==false?'selected':''}>Ativo</option><option value="false" ${c.active===false?'selected':''}>Inativo/encerrado</option></select></div></div>`,async root=>{const d=formData(root);if(!d.full_name.trim())throw new Error('Nome completo é obrigatório.');const payload={full_name:d.full_name.trim(),preferred_name:d.preferred_name||null,birth_date:d.birth_date||null,guardian_name:d.guardian_name||null,guardian_phone:d.guardian_phone||null,guardian_email:d.guardian_email||null,school:d.school||null,diagnosis:d.diagnosis||null,clinical_info:d.clinical_info||null,notes:d.notes||null,active:d.active==='true'};if(existing){const {error}=await sb.from('aba_clients').update(payload).eq('id',existing.id);if(error)throw error;await audit('update','client',existing.id)}else{payload.created_by=state.user.id;const {data,error}=await sb.from('aba_clients').insert(payload).select().single();if(error)throw error;await sb.from('aba_client_professionals').insert({client_id:data.id,professional_id:state.me.id,assignment_role:'responsible'});state.activeClientId=data.id;localStorage.setItem('wt_aba_active_client',data.id);await audit('create','client',data.id)}})}

function teamModal(cid){const current=state.assignments.filter(a=>a.client_id===cid&&a.active);openModal('Equipe do cliente',`<div class="aba-list" style="margin-bottom:12px">${current.map(a=>`<div class="aba-list-item"><b>${esc(prof(a.professional_id)?.full_name||'—')}</b><p>${esc(a.assignment_role)}</p></div>`).join('')||'<div class="aba-empty">Sem vínculos.</div>'}</div><div class="aba-form-grid"><div class="aba-field"><label>Profissional</label><select name="professional_id">${optionProfessionals()}</select></div><div class="aba-field"><label>Papel no caso</label><select name="assignment_role"><option value="professional">Profissional</option><option value="responsible">Responsável clínico</option><option value="supervisor">Supervisor</option><option value="observer">Observador</option></select></div></div>`,async root=>{const d=formData(root);const {error}=await sb.from('aba_client_professionals').insert({client_id:cid,professional_id:d.professional_id,assignment_role:d.assignment_role});if(error)throw error;await audit('link_professional','client',cid,{professional_id:d.professional_id,role:d.assignment_role})},'Adicionar vínculo')}

function professionalModal(existing=null){const p=existing||{};openModal(existing?'Editar profissional':'Novo profissional',`<div class="aba-form-grid"><div class="aba-field wide"><label>Nome completo *</label><input name="full_name" value="${esc(p.full_name||'')}"></div><div class="aba-field"><label>E-mail</label><input name="email" type="email" value="${esc(p.email||'')}"></div><div class="aba-field"><label>Registro profissional</label><input name="registration" value="${esc(p.registration||'')}"></div><div class="aba-field"><label>Especialidade</label><input name="specialty" value="${esc(p.specialty||'Psicologia / ABA')}"></div><div class="aba-field"><label>Função</label><select name="role">${['admin','supervisor','professional','viewer'].map(x=>`<option ${p.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="aba-field"><label>Status</label><select name="active"><option value="true" ${p.active!==false?'selected':''}>Ativo</option><option value="false" ${p.active===false?'selected':''}>Inativo</option></select></div><div class="aba-field wide"><label>Observações</label><textarea name="notes">${esc(p.notes||'')}</textarea></div></div>`,async root=>{const d=formData(root);if(!d.full_name.trim())throw new Error('Nome obrigatório.');const payload={full_name:d.full_name.trim(),email:d.email||null,registration:d.registration||null,specialty:d.specialty||null,role:d.role,active:d.active==='true',notes:d.notes||null};if(existing){const {error}=await sb.from('aba_professionals').update(payload).eq('id',existing.id);if(error)throw error;await audit('update','professional',existing.id)}else{const {data,error}=await sb.from('aba_professionals').insert(payload).select().single();if(error)throw error;await audit('create','professional',data.id)}})}
function supervisionLinkModal(){openModal('Vínculo de supervisão',`<div class="aba-form-grid"><div class="aba-field"><label>Supervisor</label><select name="supervisor_id">${state.professionals.filter(p=>['admin','supervisor'].includes(p.role)&&p.active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></div><div class="aba-field"><label>Supervisionado</label><select name="supervisee_id">${state.professionals.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></div><div class="aba-field wide"><label>Observação</label><textarea name="notes"></textarea></div></div>`,async root=>{const d=formData(root);if(d.supervisor_id===d.supervisee_id)throw new Error('Supervisor e supervisionado devem ser pessoas diferentes.');const {error}=await sb.from('aba_supervision_links').insert({supervisor_id:d.supervisor_id,supervisee_id:d.supervisee_id,notes:d.notes||null});if(error)throw error;await audit('create','supervision_link',null,d)})}

function criterionModal(protocolId){const p=proto(protocolId);openModal(`Novo critério · ${p?.name||protocolId}`,`<div class="aba-form-grid"><div class="aba-field"><label>Código</label><input name="criterion_code"></div><div class="aba-field"><label>Domínio *</label><input name="domain"></div><div class="aba-field wide"><label>Título/critério *</label><input name="title"></div><div class="aba-field wide"><label>Definição operacional</label><textarea name="operational_definition"></textarea></div><div class="aba-field"><label>Medida</label><input name="measure" placeholder="tentativas, frequência, duração…"></div><div class="aba-field"><label>Origem</label><select name="source_type"><option value="operational_original">Operacional original</option><option value="licensed_user_entry">Entrada do usuário licenciado</option><option value="custom">Personalizado</option></select></div></div>`,async root=>{const d=formData(root);if(!d.domain.trim()||!d.title.trim())throw new Error('Domínio e título são obrigatórios.');if(p?.official_license_required&&d.source_type==='operational_original'&&/item oficial|questão oficial/i.test(d.title))throw new Error('Conteúdo oficial de instrumento licenciado deve ser inserido apenas como entrada licenciada do usuário.');const {data,error}=await sb.from('aba_protocol_criteria').insert({protocol_id:protocolId,criterion_code:d.criterion_code||null,domain:d.domain.trim(),title:d.title.trim(),operational_definition:d.operational_definition||null,measure:d.measure||null,source_type:d.source_type}).select().single();if(error)throw error;await audit('create','protocol_criterion',data.id,{protocol_id:protocolId})})}

function assessmentModal(existing=null){const a=existing||{};openModal(existing?'Editar avaliação':'Nova avaliação',`<div class="aba-form-grid"><div class="aba-field"><label>Protocolo *</label><select name="protocol_id">${optionProtocols(a.protocol_id)}</select></div><div class="aba-field"><label>Data</label><input name="assessment_date" type="date" value="${a.assessment_date||today()}"></div><div class="aba-field"><label>Avaliador</label><select name="evaluator_id"><option value="">—</option>${optionProfessionals(a.evaluator_id)}</select></div><div class="aba-field"><label>Supervisor</label><select name="supervisor_id"><option value="">—</option>${optionProfessionals(a.supervisor_id)}</select></div><div class="aba-field"><label>Status</label><select name="status">${['draft','in_progress','completed','supervised','archived'].map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="aba-field"><label>Reavaliar em</label><input name="reeval_due" type="date" value="${a.reeval_due||''}"></div><div class="aba-field wide"><label>Interpretação</label><textarea name="interpretation">${esc(a.interpretation||'')}</textarea></div><div class="aba-field wide"><label>Observações</label><textarea name="notes">${esc(a.notes||'')}</textarea></div></div>`,async root=>{const d=formData(root);const payload={client_id:state.activeClientId,protocol_id:d.protocol_id,evaluator_id:d.evaluator_id||null,supervisor_id:d.supervisor_id||null,assessment_date:d.assessment_date||today(),status:d.status,reeval_due:d.reeval_due||null,interpretation:d.interpretation||null,notes:d.notes||null};if(existing){delete payload.client_id;const {error}=await sb.from('aba_assessments').update(payload).eq('id',existing.id);if(error)throw error;await audit('update','assessment',existing.id)}else{payload.created_by=state.user.id;const {data,error}=await sb.from('aba_assessments').insert(payload).select().single();if(error)throw error;await audit('create','assessment',data.id,{protocol_id:d.protocol_id})}})}
function resultModal(assessmentId){const a=state.assessments.find(x=>x.id===assessmentId);const criteria=state.criteria.filter(c=>c.protocol_id===a.protocol_id);openModal('Registrar resultado de avaliação',`<div class="aba-form-grid"><div class="aba-field wide"><label>Critério cadastrado</label><select name="criterion_id"><option value="">Registro manual/licenciado</option>${criteria.map(c=>`<option value="${c.id}">${esc((c.criterion_code?c.criterion_code+' · ':'')+c.domain+' · '+c.title)}</option>`).join('')}</select></div><div class="aba-field"><label>Código manual</label><input name="custom_code"></div><div class="aba-field"><label>Domínio</label><input name="domain"></div><div class="aba-field"><label>Estado</label><select name="result_state"><option value="tested">Testado</option><option value="not_tested">Não testado</option><option value="not_applicable">Não aplicável</option></select></div><div class="aba-field"><label>Escore</label><input name="score" type="number" step="0.5"></div><div class="aba-field"><label>Oportunidades</label><input name="opportunities" type="number" min="0"></div><div class="aba-field"><label>Respostas independentes</label><input name="independent_responses" type="number" min="0"></div><div class="aba-field"><label>Nível de ajuda</label><input name="prompt_level"></div><div class="aba-field"><label>Contexto</label><input name="context"></div><div class="aba-field"><label><input type="checkbox" name="generalized" style="width:auto"> Generalizado</label></div><div class="aba-field"><label><input type="checkbox" name="maintained" style="width:auto"> Mantido</label></div><div class="aba-field wide"><label>Evidência observável</label><textarea name="evidence"></textarea></div><div class="aba-field wide"><label>Notas</label><textarea name="notes"></textarea></div></div>`,async root=>{const d=formData(root);const opp=asNum(d.opportunities),ind=asNum(d.independent_responses);if(opp!=null&&ind!=null&&ind>opp)throw new Error('Respostas independentes não podem exceder oportunidades.');const payload={assessment_id:assessmentId,criterion_id:d.criterion_id||null,custom_code:d.custom_code||null,domain:d.domain||null,result_state:d.result_state,score:asNum(d.score),opportunities:opp,independent_responses:ind,prompt_level:d.prompt_level||null,context:d.context||null,generalized:bool(d.generalized),maintained:bool(d.maintained),evidence:d.evidence||null,notes:d.notes||null};const {data,error}=await sb.from('aba_assessment_results').insert(payload).select().single();if(error)throw error;await audit('create','assessment_result',data.id,{assessment_id:assessmentId})})}

function goalModal(){openModal('Nova meta clínica',`<div class="aba-form-grid"><div class="aba-field wide"><label>Título *</label><input name="title"></div><div class="aba-field"><label>Domínio</label><input name="domain"></div><div class="aba-field"><label>Medida</label><input name="measure"></div><div class="aba-field"><label>Prioridade</label><select name="priority"><option>low</option><option selected>medium</option><option>high</option><option>urgent</option></select></div><div class="aba-field"><label>Data de revisão</label><input name="review_date" type="date"></div><div class="aba-field wide"><label>Linha de base</label><textarea name="baseline"></textarea></div><div class="aba-field wide"><label>Meta mensurável</label><textarea name="target"></textarea></div><div class="aba-field wide"><label>Descrição</label><textarea name="description"></textarea></div></div>`,async root=>{const d=formData(root);if(!d.title.trim())throw new Error('Título obrigatório.');const {data,error}=await sb.from('aba_goals').insert({client_id:state.activeClientId,title:d.title.trim(),domain:d.domain||null,measure:d.measure||null,priority:d.priority,review_date:d.review_date||null,baseline:d.baseline||null,target:d.target||null,description:d.description||null,responsible_professional_id:state.me.id,created_by:state.user.id}).select().single();if(error)throw error;await audit('create','goal',data.id)})}
function programModal(existing=null){const p=existing||{};openModal(existing?'Editar programa':'Novo programa ABA',`<div class="aba-form-grid"><div class="aba-field wide"><label>Nome *</label><input name="name" value="${esc(p.name||'')}"></div><div class="aba-field"><label>Meta relacionada</label><select name="goal_id"><option value="">—</option>${optionGoals(p.goal_id)}</select></div><div class="aba-field"><label>Domínio</label><input name="domain" value="${esc(p.domain||'')}"></div><div class="aba-field"><label>Status</label><select name="status">${['baseline','acquisition','fluency','generalization','maintenance','reserve','paused','closed'].map(x=>`<option value="${x}" ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="aba-field"><label>Medida</label><select name="measure">${['trials','frequency','rate','duration','latency','intervals','occurrence'].map(x=>`<option value="${x}" ${p.measure===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="aba-field"><label>Tentativas/sessão</label><input name="trials_per_session" type="number" min="1" value="${p.trials_per_session||''}"></div><div class="aba-field"><label>Revisão em</label><input name="review_date" type="date" value="${p.review_date||''}"></div><div class="aba-field wide"><label>Objetivo clínico</label><textarea name="objective">${esc(p.objective||'')}</textarea></div><div class="aba-field wide"><label>Definição operacional</label><textarea name="operational_definition">${esc(p.operational_definition||'')}</textarea></div><div class="aba-field"><label>SD / instrução</label><textarea name="sd_instruction">${esc(p.sd_instruction||'')}</textarea></div><div class="aba-field"><label>Resposta esperada</label><textarea name="expected_response">${esc(p.expected_response||'')}</textarea></div><div class="aba-field"><label>Procedimento de ensino</label><textarea name="teaching_procedure">${esc(p.teaching_procedure||'')}</textarea></div><div class="aba-field"><label>Hierarquia de ajuda</label><textarea name="prompt_hierarchy">${esc(p.prompt_hierarchy||'')}</textarea></div><div class="aba-field"><label>Reforçamento</label><textarea name="reinforcement">${esc(p.reinforcement||'')}</textarea></div><div class="aba-field"><label>Correção de erro</label><textarea name="error_correction">${esc(p.error_correction||'')}</textarea></div><div class="aba-field"><label>Critério de aquisição</label><textarea name="acquisition_criterion">${esc(p.acquisition_criterion||'')}</textarea></div><div class="aba-field"><label>Critério de generalização</label><textarea name="generalization_criterion">${esc(p.generalization_criterion||'')}</textarea></div><div class="aba-field"><label>Critério de manutenção</label><textarea name="maintenance_criterion">${esc(p.maintenance_criterion||'')}</textarea></div><div class="aba-field"><label>Materiais</label><textarea name="materials">${esc(p.materials||'')}</textarea></div></div>`,async root=>{const d=formData(root);if(!d.name.trim())throw new Error('Nome obrigatório.');const payload={name:d.name.trim(),goal_id:d.goal_id||null,domain:d.domain||null,status:d.status,measure:d.measure,trials_per_session:asNum(d.trials_per_session),review_date:d.review_date||null,objective:d.objective||null,operational_definition:d.operational_definition||null,sd_instruction:d.sd_instruction||null,expected_response:d.expected_response||null,teaching_procedure:d.teaching_procedure||null,prompt_hierarchy:d.prompt_hierarchy||null,reinforcement:d.reinforcement||null,error_correction:d.error_correction||null,acquisition_criterion:d.acquisition_criterion||null,generalization_criterion:d.generalization_criterion||null,maintenance_criterion:d.maintenance_criterion||null,materials:d.materials||null};if(existing){const {error}=await sb.from('aba_programs').update(payload).eq('id',existing.id);if(error)throw error;await audit('update','program',existing.id)}else{Object.assign(payload,{client_id:state.activeClientId,created_by:state.user.id});const {data,error}=await sb.from('aba_programs').insert(payload).select().single();if(error)throw error;await audit('create','program',data.id)}})}
function targetModal(programId){openModal('Novo alvo',`<div class="aba-form-grid"><div class="aba-field wide"><label>Alvo *</label><input name="name"></div><div class="aba-field"><label>Estímulo/SD</label><input name="stimulus"></div><div class="aba-field"><label>Status</label><select name="status"><option>baseline</option><option>acquisition</option><option>generalization</option><option>maintenance</option><option>met</option><option>paused</option><option>closed</option></select></div><div class="aba-field wide"><label>Resposta esperada</label><textarea name="expected_response"></textarea></div><div class="aba-field wide"><label>Critério de domínio</label><textarea name="mastery_criterion"></textarea></div></div>`,async root=>{const d=formData(root);if(!d.name.trim())throw new Error('Alvo obrigatório.');const {data,error}=await sb.from('aba_targets').insert({program_id:programId,name:d.name.trim(),stimulus:d.stimulus||null,status:d.status,expected_response:d.expected_response||null,mastery_criterion:d.mastery_criterion||null}).select().single();if(error)throw error;await audit('create','target',data.id,{program_id:programId})})}

function sessionModal(){openModal('Iniciar sessão',`<div class="aba-form-grid"><div class="aba-field"><label>Profissional</label><select name="professional_id">${optionProfessionals(state.me.id)}</select></div><div class="aba-field"><label>Supervisor</label><select name="supervisor_id"><option value="">—</option>${optionProfessionals()}</select></div><div class="aba-field"><label>Modalidade</label><select name="modality"><option>Presencial</option><option>Domiciliar</option><option>Escolar</option><option>Teleatendimento</option><option>Comunidade</option></select></div><div class="aba-field"><label>Contexto</label><input name="context" placeholder="sala, NET, escola, casa…"></div><div class="aba-field wide"><label>Notas iniciais / variáveis relevantes</label><textarea name="notes"></textarea></div></div>`,async root=>{const d=formData(root);const {data,error}=await sb.from('aba_sessions').insert({client_id:state.activeClientId,professional_id:d.professional_id||state.me.id,supervisor_id:d.supervisor_id||null,modality:d.modality,context:d.context||null,notes:d.notes||null,status:'open',created_by:state.user.id}).select().single();if(error)throw error;state.activeSessionId=data.id;await audit('start','session',data.id)})}
function closeSessionModal(s){openModal('Finalizar sessão',`<div class="aba-form-grid"><div class="aba-field"><label>Integridade de aplicação (%)</label><input name="integrity_pct" type="number" min="0" max="100" step="0.1"></div><div class="aba-field"><label>IOA (%)</label><input name="ioa_pct" type="number" min="0" max="100" step="0.1"></div><div class="aba-field wide"><label>Observações finais</label><textarea name="notes">${esc(s.notes||'')}</textarea></div></div>`,async root=>{const d=formData(root);const {error}=await sb.from('aba_sessions').update({status:'completed',ended_at:new Date().toISOString(),integrity_pct:asNum(d.integrity_pct),ioa_pct:asNum(d.ioa_pct),notes:d.notes||null}).eq('id',s.id);if(error)throw error;if(state.activeSessionId===s.id)state.activeSessionId=null;await audit('complete','session',s.id,{integrity_pct:d.integrity_pct,ioa_pct:d.ioa_pct})},'Finalizar sessão')}
async function recordTrial(sessionId,programId,result){const {data,error}=await sb.from('aba_trials').insert({session_id:sessionId,program_id:programId,result}).select().single();if(error){flash(error.message,'bad');return}state.trials.unshift(data);await audit('record','trial',data.id,{session_id:sessionId,program_id:programId,result});renderSessions();bindViewActions()}

function behaviorModal(){const active=state.sessions.find(s=>s.client_id===state.activeClientId&&s.status==='open');openModal('Registro comportamental / ABC',`<div class="aba-form-grid"><div class="aba-field wide"><label>Topografia observável *</label><input name="topography"></div><div class="aba-field"><label>Sessão</label><select name="session_id"><option value="">Sem sessão vinculada</option>${state.sessions.filter(s=>s.client_id===state.activeClientId).slice(0,20).map(s=>`<option value="${s.id}" ${active?.id===s.id?'selected':''}>${dt(s.started_at)} · ${esc(s.status)}</option>`).join('')}</select></div><div class="aba-field"><label>Função hipotetizada</label><select name="hypothesized_function"><option value="">Indefinida</option><option>Atenção</option><option>Fuga / esquiva</option><option>Tangível</option><option>Automático / sensorial</option><option>Múltipla</option></select></div><div class="aba-field wide"><label>Antecedente</label><textarea name="antecedent"></textarea></div><div class="aba-field wide"><label>Comportamento / descrição adicional</label><textarea name="notes"></textarea></div><div class="aba-field wide"><label>Consequência</label><textarea name="consequence"></textarea></div><div class="aba-field"><label>Frequência</label><input name="frequency" type="number" min="0"></div><div class="aba-field"><label>Duração (s)</label><input name="duration_seconds" type="number" min="0" step="0.1"></div><div class="aba-field"><label>Latência (s)</label><input name="latency_seconds" type="number" min="0" step="0.1"></div><div class="aba-field"><label>Intensidade</label><select name="intensity"><option value="">—</option><option>Leve</option><option>Moderada</option><option>Alta</option><option>Crítica</option></select></div><div class="aba-field wide"><label>Contexto</label><input name="context"></div></div>`,async root=>{const d=formData(root);if(!d.topography.trim())throw new Error('Topografia obrigatória.');const {data,error}=await sb.from('aba_behavior_records').insert({session_id:d.session_id||null,client_id:state.activeClientId,professional_id:state.me.id,topography:d.topography.trim(),antecedent:d.antecedent||null,consequence:d.consequence||null,hypothesized_function:d.hypothesized_function||null,frequency:asNum(d.frequency),duration_seconds:asNum(d.duration_seconds),latency_seconds:asNum(d.latency_seconds),intensity:d.intensity||null,context:d.context||null,notes:d.notes||null}).select().single();if(error)throw error;await audit('create','behavior_record',data.id)})}
function preferenceModal(){openModal('Avaliação de preferência / reforçador',`<div class="aba-form-grid"><div class="aba-field"><label>Procedimento</label><select name="assessment_type"><option>MSWO</option><option>Paired-Stimulus</option><option>Free-Operant</option><option>Single-Stimulus</option><option>Brief Reinforcer Assessment</option><option>Naturalistic Observation</option></select></div><div class="aba-field"><label>Sessão</label><select name="session_id"><option value="">—</option>${state.sessions.filter(s=>s.client_id===state.activeClientId).slice(0,20).map(s=>`<option value="${s.id}">${dt(s.started_at)}</option>`).join('')}</select></div><div class="aba-field wide"><label>Itens apresentados (um por linha)</label><textarea name="items"></textarea></div><div class="aba-field wide"><label>Ranking/resultado (ordem, um por linha)</label><textarea name="ranking"></textarea></div><div class="aba-field wide"><label>Observações</label><textarea name="notes"></textarea></div></div>`,async root=>{const d=formData(root);const items=d.items.split(/\n+/).map(x=>x.trim()).filter(Boolean),ranking=d.ranking.split(/\n+/).map(x=>x.trim()).filter(Boolean);const {data,error}=await sb.from('aba_preference_assessments').insert({client_id:state.activeClientId,session_id:d.session_id||null,assessment_type:d.assessment_type,performed_by:state.me.id,items,ranking,notes:d.notes||null}).select().single();if(error)throw error;await audit('create','preference_assessment',data.id,{type:d.assessment_type})})}
function supervisionModal(){const linked=state.assignments.filter(a=>a.client_id===state.activeClientId&&a.active).map(a=>a.professional_id);openModal('Registrar supervisão',`<div class="aba-form-grid"><div class="aba-field"><label>Supervisor</label><select name="supervisor_id">${state.professionals.filter(p=>['admin','supervisor'].includes(p.role)&&p.active).map(p=>`<option value="${p.id}" ${p.id===state.me.id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></div><div class="aba-field"><label>Supervisionado</label><select name="supervisee_id">${state.professionals.filter(p=>linked.includes(p.id)&&p.active).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select></div><div class="aba-field"><label>Sessão vinculada</label><select name="session_id"><option value="">—</option>${state.sessions.filter(s=>s.client_id===state.activeClientId).slice(0,20).map(s=>`<option value="${s.id}">${dt(s.started_at)}</option>`).join('')}</select></div><div class="aba-field"><label>Status</label><select name="status"><option>completed</option><option>planned</option><option>follow_up</option></select></div><div class="aba-field"><label>Integridade (%)</label><input name="integrity_pct" type="number" min="0" max="100"></div><div class="aba-field"><label>IOA (%)</label><input name="ioa_pct" type="number" min="0" max="100"></div><div class="aba-field wide"><label>Feedback</label><textarea name="feedback"></textarea></div><div class="aba-field wide"><label>Plano de ação</label><textarea name="action_plan"></textarea></div></div>`,async root=>{const d=formData(root);if(!d.supervisee_id)throw new Error('Vincule um profissional ao cliente antes da supervisão.');const {data,error}=await sb.from('aba_supervisions').insert({client_id:state.activeClientId,session_id:d.session_id||null,supervisor_id:d.supervisor_id,supervisee_id:d.supervisee_id,status:d.status,integrity_pct:asNum(d.integrity_pct),ioa_pct:asNum(d.ioa_pct),feedback:d.feedback||null,action_plan:d.action_plan||null}).select().single();if(error)throw error;await audit('create','supervision',data.id)})}

function bindViewActions(){
  $$('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go));
  $('[data-client-new]')?.addEventListener('click',()=>clientModal());$$('[data-client-edit]').forEach(b=>b.onclick=()=>clientModal(state.clients.find(x=>x.id===b.dataset.clientEdit)));$$('[data-client-open]').forEach(b=>b.onclick=()=>{state.activeClientId=b.dataset.clientOpen;localStorage.setItem('wt_aba_active_client',state.activeClientId);renderClientPicker();setView('dashboard')});$$('[data-client-team]').forEach(b=>b.onclick=()=>teamModal(b.dataset.clientTeam));
  $('[data-prof-new]')?.addEventListener('click',()=>professionalModal());$$('[data-prof-edit]').forEach(b=>b.onclick=()=>professionalModal(state.professionals.find(x=>x.id===b.dataset.profEdit)));$('[data-supervision-link]')?.addEventListener('click',supervisionLinkModal);
  $('#abaProtocolSearch')?.addEventListener('input',renderProtocols);$$('[data-criterion-new]').forEach(b=>b.onclick=()=>criterionModal(b.dataset.criterionNew));
  $('[data-assessment-new]')?.addEventListener('click',()=>assessmentModal());$$('[data-assessment-open]').forEach(b=>b.onclick=()=>assessmentDetail(b.dataset.assessmentOpen));$$('[data-assessment-edit]').forEach(b=>b.onclick=()=>assessmentModal(state.assessments.find(x=>x.id===b.dataset.assessmentEdit)));$$('[data-result-new]').forEach(b=>b.onclick=()=>resultModal(b.dataset.resultNew));
  $('[data-goal-new]')?.addEventListener('click',goalModal);$('[data-program-new]')?.addEventListener('click',()=>programModal());$$('[data-program-edit]').forEach(b=>b.onclick=()=>programModal(state.programs.find(x=>x.id===b.dataset.programEdit)));$$('[data-target-new]').forEach(b=>b.onclick=()=>targetModal(b.dataset.targetNew));
  $('[data-session-new]')?.addEventListener('click',sessionModal);$$('[data-session-open]').forEach(b=>b.onclick=()=>{state.activeSessionId=b.dataset.sessionOpen;renderSessions();bindViewActions()});$$('[data-session-close]').forEach(b=>b.onclick=()=>closeSessionModal(state.sessions.find(x=>x.id===b.dataset.sessionClose)));$$('[data-trial]').forEach(b=>b.onclick=()=>recordTrial(b.dataset.session,b.dataset.program,b.dataset.trial));
  $('[data-behavior-new]')?.addEventListener('click',behaviorModal);$('[data-preference-new]')?.addEventListener('click',preferenceModal);$('[data-supervision-new]')?.addEventListener('click',supervisionModal);
  $('[data-report-print]')?.addEventListener('click',()=>{$$('.aba-view').forEach(v=>v.classList.remove('printing'));$('#abaView-reports').classList.add('printing');window.print();$('#abaView-reports').classList.remove('printing')});$('[data-report-save]')?.addEventListener('click',async()=>{const c=client();const content=buildReportData(c);const {data,error}=await sb.from('aba_reports').insert({client_id:c.id,report_type:'clinical_longitudinal',title:`Relatório de acompanhamento ABA — ${c.full_name}`,content,generated_by:state.me.id}).select().single();if(error){flash(error.message,'bad');return}await audit('create','report',data.id);await loadAll();flash('Versão do relatório salva.')});
}

$('#abaNav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)setView(b.dataset.view)});
$('#abaActiveClient').addEventListener('change',e=>{state.activeClientId=e.target.value;localStorage.setItem('wt_aba_active_client',state.activeClientId);render()});
$('#abaRefresh').addEventListener('click',()=>loadAll().catch(e=>flash(e.message,'bad')));
$('#abaLogout').addEventListener('click',async()=>{await sb.auth.signOut();location.replace('/sistema-aba-login.html')});
$('#abaModalCancel').addEventListener('click',closeModal);$('#abaModal').addEventListener('click',e=>{if(e.target.id==='abaModal')closeModal()});

(async()=>{try{if(!await authGate())return;await loadAll();await audit('login','module',null,{role:state.me.role})}catch(err){console.error(err);flash('Não foi possível carregar o Sistema ABA: '+(err?.message||err),'bad')}})();
